  --me-icon-chevron-right: "";
  --me-icon-close: "";
  --me-icon-filter-alt: "";
  --me-icon-group-closed: "";
  --me-icon-lock: "";
  --me-icon-minimize: "";
  --me-icon-more-vert: "";
  --me-icon-remove: "";
  --me-icon-search: "";
  --me-icon-sort-up: "";
  --me-icon-more-vert: "";
  --me-icon-close: "";
  --me-icon-eye: "";
  --me-icon-eyeoff: "";
