}

:root {
  /* Font weights */
  --me-thin-font-weight: 100;
  --me-light-font-weight: 300;
  --me-regular-font-weight: 400;
  --me-medium-font-weight: 500;
  --me-bold-font-weight: 700;
}

:root {
  /* Small tabs */
  --me-tabs-small-height: 28px;
  --me-tabs-small-font-size: 13px;
  --me-tabs-small-font-weight: 400;
  --me-tabs-small-tab-padding: 3px 6px;
  --me-tabs-small-line-height: 16px;
  --me-tabs-small-icon-margin-right: 4px;
  --me-tabs-small-icon-font-size: 20px;
  /* Medium tabs */
  --me-tabs-medium-height: 42px;
  --me-tabs-medium-font-size: 14px;
  --me-tabs-medium-font-weight: 400;
  --me-tabs-medium-tab-padding: 10px 8px;
  --me-tabs-medium-line-height: 20px;
  --me-tabs-medium-icon-font-size: 20px;
  /* Large tabs */
  --me-tabs-large-height: 40px;
  --me-tabs-large-font-size: 16px;
  --me-tabs-large-font-weight: 400;
  --me-tabs-large-line-height: 20px;
  --me-tabs-large-icon-font-size: 24px;
}

:root {
  /* Общие шрифты */
  --accordion-font-family: "Roboto", sans-serif;
  --font-family: "Roboto", sans-serif;
  /* Иконки */
  --accordion-icon-color: #000000;
  --accordion-icon-margin-right: 10px;
  /* Размеры иконок */
  --accordion-icon-size-small: 16px;
  --accordion-icon-size-medium: 20px;
  --accordion-icon-size-large: 20px;
  /* Описание заголовка */
  --accordion-description-color: rgba(128, 128, 132, 1);
  /* Маленький размер */
  --accordion-title-font-weight-small: 600;
  --accordion-title-font-size-small: 14px;
  --accordion-title-line-height-small: 20px;
  --accordion-description-font-weight-small: 400;
  --accordion-description-font-size-small: 12px;
  --accordion-description-line-height-small: 16px;
  --accordion-body-font-weight-small: 400;
  --accordion-body-font-size-small: 14px;
  --accordion-body-line-height-small: 20px;
  /* Средний размер */
  --accordion-title-font-weight-medium: 600;
  --accordion-title-font-size-medium: 20px;
  --accordion-title-line-height-medium: 24px;
  --accordion-description-font-weight-medium: 400;
  --accordion-description-font-size-medium: 14px;
  --accordion-description-line-height-medium: 20px;
  --accordion-body-font-weight-medium: 400;
  --accordion-body-font-size-medium: 14px;
  --accordion-body-line-height-medium: 20px;
  /* Большой размер */
  --accordion-title-font-weight-large: 600;
  --accordion-title-font-size-large: 24px;
  --accordion-title-line-height-large: 30px;
  --accordion-description-font-weight-large: 400;
  --accordion-description-font-size-large: 16px;
  --accordion-description-line-height-large: 24px;
  --accordion-body-font-weight-large: 400;
  --accordion-body-font-size-large: 16px;
  --accordion-body-line-height-large: 24px;
}

:root {
  /* Select Box Styles */
  --controls-content-in-controls-main-default: #18181a;
  --controls-content-in-controls-main-disabled: rgba(24, 24, 26, 0.4);
  --controls-content-in-controls-accent-default: rgba(50, 87, 220, 1);
  --controls-bg-accent-accent-bg-default: rgba(50, 87, 220, 1);
  --dividers-borders-long: #dfe0ed;
  --background-accent-in-the-content: #fff;
  /* Select Box Typography */
  --select-box-font-family: var(--font-family, "Roboto", sans-serif);
  --select-box-font-size: 16px;
  --select-box-font-weight: var(--me-regular-font-weight, 400);
  --select-box-line-height: 20px;
  /* Select Box Dimensions */
  --select-box-border-radius: 4px;
  --select-box-box-shadow: 0px 2px 6px 0px rgba(0, 0, 0, 0.14);
  /* Select Box States */
  --select-box-hover-border-color: var(--controls-content-in-controls-accent-default);
  --select-box-focus-border-color: var(--controls-content-in-controls-accent-default);
  --select-box-focus-box-shadow: 0 0 0 3px var(--controls-content-in-controls-accent-default);
}

:root {
  --outside: 4px;
  --inside-elements: 3px;
  --inner: 2;
  --modal-shadow-color: rgba(0, 0, 0, 0.22);
  --modal-shadow: 0px 4px 10px 0px var(--modal-shadow-color);
  --drop-down-shadow-color: rgba(0, 0, 0, 0.14);
  --drop-down-shadow: 0px 2px 6px 0px var(--drop-down-shadow-color);
  --vertical-dividers: 1px;
  --horizontal-dividers: 1px;
}

