.dx-invalid-message.dx-overlay {
  position: relative;
}
.dx-invalid-message.dx-overlay-wrapper {
  width: 100%;
  visibility: hidden;
  pointer-events: none;
}
.dx-invalid-message > .dx-overlay-content {
  display: inline-block;
  border-width: 0;
  padding: 10px;
  font-size: 0.85em;
  line-height: normal;
  word-wrap: break-word;
  text-align: left;
}
.me-editor .dx-invalid-message > .dx-overlay-content {
  display: flex;
  padding: 2px 8px;
  border-radius: 3px;
  line-height: 16px;
  font-size: 12px;
  color: #dd0035;
  background-color: #ffe0e2;
}
.me-editor.me-editor-medium .dx-invalid-message > .dx-overlay-content {
  padding: 4px 8px;
}
.me-editor.me-editor-large .dx-invalid-message > .dx-overlay-content {
  padding: 4px 12px;
  font-size: 14px;
  line-height: 20px;
}

.dx-state-focused.dx-invalid .dx-invalid-message-auto,
.dx-invalid-message-visible.dx-invalid .dx-invalid-message-auto,
